update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Bitcoin is a company like BCA Bank that can be supervised by the OJK.","difficulty":"beginner","explanation":"Bitcoin is not a company and is not supervised by the OJK as a financial institution. In Indonesia, crypto is regulated as a commodity by Bappebti."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Bitcoin adalah perusahaan seperti Bank BCA yang bisa diawasi OJK.","difficulty":"beginner","explanation":"Bitcoin bukan perusahaan dan tidak diawasi OJK sebagai lembaga keuangan. Di Indonesia, kripto diatur sebagai komoditas oleh Bappebti."}$json$::jsonb where id = 'f11e7f37-bbe2-4787-b819-7bfdef49e215';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Exchange licensed by CoFTRA","options":["Exchange licensed by CoFTRA","Private WhatsApp group","Instagram account that offers low prices","Unauthorized overseas application"],"question":"In Indonesia, legal crypto trading must go through...","difficulty":"beginner","explanation":"Only exchanges registered with CoFTRA may legally carry out crypto asset trading."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Bursa berizin Bappebti","options":["Bursa berizin Bappebti","Grup WhatsApp pribadi","Akun Instagram yang menawarkan harga murah","Aplikasi luar negeri tanpa izin"],"question":"Di Indonesia, perdagangan kripto yang legal harus melalui...","difficulty":"beginner","explanation":"Hanya bursa yang terdaftar di Bappebti yang boleh menyelenggarakan perdagangan aset kripto secara legal."}$json$::jsonb where id = 'f184f1b8-213b-417a-9fc4-71cc817ecb07';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Speculation","options":["Speculation","Productive investment","Savings","Insurance"],"question":"Buying crypto in the hope of its price doubling in a week includes...","difficulty":"beginner","explanation":"Speculation is betting on rapid price increases without generating real income or economic growth."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Spekulasi","options":["Spekulasi","Investasi produktif","Tabungan","Asuransi"],"question":"Membeli kripto dengan harapan harganya berlipat dalam seminggu termasuk...","difficulty":"beginner","explanation":"Spekulasi adalah bertaruh pada kenaikan harga cepat tanpa menghasilkan pendapatan atau pertumbuhan ekonomi nyata."}$json$::jsonb where id = 'f535312a-4e96-461d-8054-18cb856cdc0a';
update public.content_variants set body = $json${"text":"Andi read that the price of Bitcoin had fallen from IDR 1 billion to IDR 700 million in a few weeks. He realized crypto was very volatile and not a place to store money needed in the near future."}$json$::jsonb, body_id = $json${"text":"Andi membaca bahwa harga Bitcoin pernah turun dari Rp 1 miliar menjadi Rp 700 juta dalam beberapa minggu. Ia menyadari kripto sangat volatil dan bukan tempat untuk menyimpan uang yang dibutuhkan dalam waktu dekat."}$json$::jsonb where id = 'f5d42115-3bf5-4183-8a5c-1be2f53e5498';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"If you have money you can afford to lose and understand the risks","options":["If you have money you can afford to lose and understand the risks","If you need the money in one month","If you borrow money for speculation","If you feel FOMO because a friend has made a profit"],"question":"When can speculation be considered?","difficulty":"beginner","explanation":"Speculation should only be done with money you are willing to lose and after understanding the high risks involved."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Jika kamu punya uang yang sanggup hilang dan memahami risikonya","options":["Jika kamu punya uang yang sanggup hilang dan memahami risikonya","Jika kamu membutuhkan uang itu dalam satu bulan","Jika kamu meminjam uang untuk spekulasi","Jika kamu merasa FOMO karena teman sudah untung"],"question":"Kapan spekulasi bisa dipertimbangkan?","difficulty":"beginner","explanation":"Spekulasi hanya boleh dengan uang yang rela hilang dan setelah memahami risiko tinggi yang dihadapi."}$json$::jsonb where id = 'f60d950a-22ca-42b4-99d5-6b44cff6310c';
update public.content_variants set body = $json${"text":"Bayu has IDR 5,000,000 for investment. He can buy 100 BBCA shares for IDR 855,000 or 1 LQ45 ETF unit for IDR 500,000. If he buys BBCA shares and BBCA falls 20%, Bayu will suffer a big loss. But if he buys the LQ45 ETF, the decrease in BBCA will only have a small effect because there are still 44 other shares in the ETF."}$json$::jsonb, body_id = $json${"text":"Bayu punya Rp 5.000.000 untuk investasi. Dia bisa beli 100 lembar saham BBCA seharga Rp 855.000 atau 1 unit ETF LQ45 seharga Rp 500.000. Kalau dia beli saham BBCA dan BBCA turun 20%, Bayu rugi besar. Tapi kalau dia beli ETF LQ45, penurunan BBCA hanya berpengaruh kecil karena masih ada 44 saham lain di ETF."}$json$::jsonb where id = 'f74de1ee-26e3-4dcf-99e3-45f35c270e75';
update public.content_variants set body = $json${"type":"fill_blank","answer":"down","question":"Bad debt is often used to buy goods that quickly _____ their value.","difficulty":"beginner","explanation":"Items such as clothes, gadgets or vacations quickly lose value once purchased."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"turun","question":"Utang buruk sering digunakan untuk membeli barang yang cepat _____ nilainya.","difficulty":"beginner","explanation":"Barang seperti pakaian, gadget, atau liburan cepat kehilangan nilai setelah dibeli."}$json$::jsonb where id = 'f9f1d6b3-7f34-42aa-af8a-f03ce072a546';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"You can ignore small debts and focus only on the largest debts.","difficulty":"beginner","explanation":"Small debts that are paid late can still result in fines and damage to your credit record. Pay the minimum on all debts first."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Kamu boleh mengabaikan utang kecil dan fokus hanya pada utang terbesar.","difficulty":"beginner","explanation":"Utang kecil yang telat bayar tetap bisa kena denda dan merusak rekam kredit. Bayar minimum semua utang terlebih dahulu."}$json$::jsonb where id = 'fcc59fa0-1c4f-4d7c-a292-0c6b5a15d3b6';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"All debt is bad and should be avoided.","difficulty":"beginner","explanation":"Not all debt is bad. Loans for education or productive businesses can become good debt if planned well."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Semua utang pasti buruk dan harus dihindari.","difficulty":"beginner","explanation":"Tidak semua utang buruk. Pinjaman untuk pendidikan atau usaha produktif bisa menjadi utang baik jika direncanakan dengan baik."}$json$::jsonb where id = 'fcf8b875-8de1-47ae-9e3f-0a1aaeecf73c';

